css:
.card {
  width: 300px;
  height: 254px;
  background: #141414;
  overflow: hidden;
  display: flex;
  border-radius: 7px;
}

.circles,
.browser {
  height: 30px;
  display: flex;
  align-items: center;
  border-bottom: 1px solid rgb(255 239 255 / 15%);
}

.circles {
  width: 20%;
  gap: 8px;
  padding: 10px;
}

.c {
  width: 09px;
  height: 9px;
  border-radius: 50%;
  box-shadow: inset 2px 2px 5px #ffffff25;
}

.c:first-child {
  background-color: red;
}

.c:nth-child(2) {
  background-color: rgb(204, 167, 4);
}

.c:last-child {
  background-color: green;
}

.browser {
  width: 80%;
  padding: 5px;
  display: flex;
  gap: 10px;
}

.chevrons {
  display: flex;
}

.search-bar {
  position: relative;
  border: 0.5px solid #fff;
  border-radius: 5px;
  padding: 5px;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: rgb(204, 204, 204);
  box-shadow: inset 2px 2px 2px #ffffff25;
}

.search-bar svg {
  position: absolute;
  left: 10px;
}
